class AffiliateCreatorApi(SyncGroup):
    """Operations tagged \"Affiliate creator\"."""

    def add_showcase_products(
        self,
        *,
        body: AddShowcaseProductsRequest,
    ) -> AddShowcaseProductsResponse | None:
        """Add Showcase Products

         This API adds products to the authenticated creator's showcase. Global Shop users must have at least
        one selected region before calling this API. A successful API response can still contain `errors`
        for products that were not added; when there are no product-level addition errors, `errors` is
        omitted.

        Args:
            body (AddShowcaseProductsRequest):

        Raises:
            TikTokShopError: for a TikTok error code, a non-2xx status,
                an unparseable response, a network error or a timeout.
        """
        from .api.affiliate_creator import add_showcase_products as _op

        return self._run(_op.sync_detailed, body=body)

    def check_creator_sample_eligibility(
        self,
        *,
        product_id: str,
    ) -> CheckCreatorSampleEligibilityResponse | None:
        """Check Creator Sample Eligibility

         Check if a creator can apply for a sample of a specific product.

        Args:
            product_id (str):

        Raises:
            TikTokShopError: for a TikTok error code, a non-2xx status,
                an unparseable response, a network error or a timeout.
        """
        from .api.affiliate_creator import check_creator_sample_eligibility as _op

        return self._run(_op.sync_detailed, product_id=product_id)

