class ProductsApi(SyncGroup):
    """Operations tagged \"Products\"."""

    def activate_products(
        self,
        *,
        body: ActivateProductsRequest,
    ) -> ActivateProductsResponse | None:
        """Activate Products

         Activate hidden products that are in the `Seller_deactivated` or `Platform_deactivated` status and
        display them in the TikTok Shop catalog.
        After submitting the activation request, the products will be sent to TikTok Shop for auditing and
        their status will change to `Pending`. If a product passes the audit, its status will change back to
        `Activate`. You can use the [Product status change
        webhook](https://partner.tiktokshop.com/docv2/page/650956aff1fd3102b90b6261) to monitor the audit
        status.

        Args:
            body (ActivateProductsRequest):

        Raises:
            TikTokShopError: for a TikTok error code, a non-2xx status,
                an unparseable response, a network error or a timeout.
        """
        from .api.products import activate_products as _op

        return self._run(_op.sync_detailed, body=body)

    def check_listing_prerequisites(
        self,
    ) -> CheckListingPrerequisitesResponse | None:
        """Check Listing Prerequisites

         Check if a TikTok shop is ready to list products.
        Each shop needs to satisfy a series of TikTok Shop requirements before you can start listing
        products. Before you proceed to list products, use this API to check if your shop has satisfied all
        requirements.
        **Tip**: We recommend that you run this check before any bulk updates to avoid listing issues. For
        example, sellers may change the delivery option to "Shipped by seller" but fail to add a shipping
        template, thus blocking the shop from listing products. In this case, the API would return
        `is_failed=true` for the `SHIPPING_TEMPLATE` check item and you can prompt the seller to fix the
        problem.

        Raises:
            TikTokShopError: for a TikTok error code, a non-2xx status,
                an unparseable response, a network error or a timeout.
        """
        from .api.products import check_listing_prerequisites as _op

        return self._run(_op.sync_detailed)

    def check_product_listing(
        self,
        *,
        body: CheckProductListingRequest,
        is_diagnosis_required: bool | Unset = UNSET,
    ) -> CheckProductListingResponse | None:
        """Check Product Listing

         Identify any issues with your product properties in advance to ensure your product is ready for
        listing.
        Every product must meet TikTok Shop requirements before it can be listed. Before listing, you can
        submit all relevant product information to this API to check whether a listing meets these
        requirements. You'll receive a list of issues to resolve before listing. This process helps reduce
        the risk of failure when creating products.
        **Note**:
        - The language used in the product content must align with the target market's language (e.g. don't
        use Chinese), otherwise the listing will fail or be rejected.

        Args:
            is_diagnosis_required (bool | Unset):
            body (CheckProductListingRequest):

        Raises:
            TikTokShopError: for a TikTok error code, a non-2xx status,
                an unparseable response, a network error or a timeout.
        """
